// This file holds global configuration for the frontend

// Define the base URL for the backend API
window.API_BASE_URL = 'https://wargmirror.onrender.com';

if (window.location.hostname === 'localhost' || window.location.hostname === '127.0.0.1') {
  window.API_BASE_URL = 'http://localhost:3000';
}

/**
 * WARG Platform — Shared API Client
 * ==================================
 * Provides typed helpers for every backend endpoint and a normaliser
 * that maps API response shapes to the GameCard-compatible format.
 *
 * Usage (plain-script — no import needed, loaded before page scripts):
 *   const args = await api.getArgs();
 *   const user = await api.getCurrentUser(); // null for guests
 */

// Auto-detect local development environment
if (!window.API_BASE_URL) {
  if (window.location.hostname === 'localhost' || window.location.hostname === '127.0.0.1') {
    window.API_BASE_URL = 'http://localhost:3000';
  } else {
    window.API_BASE_URL = 'https://wargmirror.onrender.com';
  }
}
var API_BASE = window.API_BASE_URL;

// eslint-disable-next-line no-unused-vars
var api = (function () {

  /* ── Generic fetch wrapper ──────────────────────────────── */
  async function _get(path) {
    const res = await fetch(API_BASE + path, { credentials: 'include' });
    if (!res.ok) {
      throw Object.assign(new Error('API error'), { status: res.status, path });
    }
    return res.json();
  }

  async function _post(path, body) {
    const res = await fetch(API_BASE + path, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify(body),
      credentials: 'include'
    });
    if (!res.ok) {
      throw Object.assign(new Error('API error'), { status: res.status, path });
    }
    return res.json();
  }

  async function _delete(path) {
    const res = await fetch(API_BASE + path, {
      method: 'DELETE',
      credentials: 'include'
    });
    if (!res.ok) {
      throw Object.assign(new Error('API error'), { status: res.status, path });
    }
    return res.json();
  }

  /* ── Data normaliser ────────────────────────────────────── */
  /**
   * Maps an API Arg object → GameCard-compatible shape.
   *
   * API shape:
   *   { arg_id, title, mode, caption, cover_image, like_count, dislike_count,
   *     rating_sum, rating_count, status, play_count, created_at, updated_at,
   *     Creator: { username, avatar } }
   *
   * GameCard shape:
   *   { id, title, mode, caption, emoji, image, progress, progressLabel,
   *     author: { name, initials }, likes, dislikes, rating, featured }
   */
  function normaliseArg(arg) {
    var creator  = arg.Creator || {};
    var username = creator.username || 'Unknown';

    // Build initials from username (up to 2 chars)
    var initials = username
      .split(/[\s_-]+/)
      .slice(0, 2)
      .map(function (w) { return w[0] || ''; })
      .join('')
      .toUpperCase() || '??';

    // Compute rating (0 if never rated)
    var ratingCount = arg.rating_count || 0;
    var rating = ratingCount > 0
      ? Math.round((arg.rating_sum / ratingCount) * 10) / 10
      : 0;

    // cover_image from the DB is a BLOB — the API sends it as a Buffer/null.
    // Until the server serialises it as a data-URL we default to null (emoji fallback).
    var image = null;

    return {
      id:            String(arg.arg_id),
      title:         arg.title        || 'Untitled',
      mode:          arg.mode         || 'solo',
      caption:       arg.caption      || '',
      emoji:         '🎮',
      image:         image,
      progress:      null,
      progressLabel: null,
      author: {
        name:     username,
        initials: initials,
      },
      likes:    arg.like_count    || 0,
      dislikes: arg.dislike_count || 0,
      userVote: arg.user_vote     || null,
      rating:   rating,
      featured: false,
      // Keep raw fields for pages that need them
      _raw: arg,
    };
  }

  /* ── Endpoints ──────────────────────────────────────────── */

  /**
   * Returns the currently authenticated user, or null for guests.
   * Never throws — a 401 is silently swallowed.
   */
  async function getCurrentUser() {
    try {
      return await _get('/auth/me');
    } catch (err) {
      if (err.status === 401) return null;
      throw err;
    }
  }

  /**
   * Returns all published ARGs normalised for GameCard.
   * Public endpoint — works for guests.
   */
  async function getArgs() {
    const args = await _get('/api/args');
    return args.map(normaliseArg);
  }

  /**
   * Returns a single ARG (with Waypoints) normalised for GameCard.
   */
  async function getArgById(id) {
    const arg = await _get('/api/args/' + id);
    return normaliseArg(arg);
  }

  /**
   * Returns a user's public profile.
   * Requires authentication (caller must check for 401).
   */
  async function getUserProfile(userId) {
    return _get('/api/users/' + userId);
  }

  /**
   * Returns all ARGs created by a user (any status), normalised.
   * Requires authentication.
   */
  async function getUserLibrary(userId) {
    const args = await _get('/api/users/' + userId + '/library');
    return args.map(normaliseArg);
  }

  /**
   * Returns active game sessions for a user.
   * Requires authentication.
   */
  async function getActiveSessions(userId) {
    return _get('/api/sessions/' + userId);
  }

  /**
   * Returns friends of a user.
   * Requires authentication.
   */
  async function getFriends(userId) {
    return _get('/api/users/' + userId + '/friends');
  }

  /* ── Game Actions ───────────────────────────────────────── */
  async function voteArg(argId, voteType, userId = 1) { // Defaulting user_id to 1 until auth is hooked up
    return _post('/api/args/' + argId + '/vote', { vote: voteType, user_id: userId });
  }

  async function flagArg(argId, reason, description, reporterId = 1) { // Defaulting user_id to 1 until auth is hooked up
    return _post('/api/args/' + argId + '/flag', { reason, description, reporter_id: reporterId });
  }

  async function removeRecentArg(argId, userId = 1) { // Defaulting user_id to 1 until auth is hooked up
    return _delete('/api/sessions/' + userId + '/arg/' + argId);
  }

  async function submitFeedback(feedbackData) {
    return _post('/api/feedback', feedbackData);
  }

  /* ── Public API ─────────────────────────────────────────── */
  return {
    getCurrentUser,
    getArgs,
    getArgById,
    getUserProfile,
    getUserLibrary,
    getActiveSessions,
    getFriends,
    normaliseArg,
    voteArg,
    flagArg,
    removeRecentArg,
    submitFeedback,
  };

}());

/**
 * WARG Platform — GameCard Component
 * ===================================
 * Factory that creates a fully-featured game card DOM element.
 * Usage:
 *   const card = GameCard.create(gameObject);
 *   container.appendChild(card);
 *
 *   // Or fill an entire row at once:
 *   GameCard.renderRow('row-recent', WARG_GAMES.recent);
 */


// eslint-disable-next-line no-unused-vars
var GameCard = (function () {

  /* ── Mode configuration ─────────────────────────────── */
  var MODE = {
    solo: {
      label:     'Solo',
      badgeClass:'badge--solo',
      bg:        'linear-gradient(145deg,#141028 0%,#1e1840 100%)',
      glowColor: 'rgba(153,172,255,0.18)',
    },
    coop: {
      label:     'Co-op',
      badgeClass:'badge--coop',
      bg:        'linear-gradient(145deg,#081408 0%,#0e2810 100%)',
      glowColor: 'rgba(51,255,51,0.14)',
    },
    pvp: {
      label:     'PvP',
      badgeClass:'badge--pvp',
      bg:        'linear-gradient(145deg,#180808 0%,#2a0e0e 100%)',
      glowColor: 'rgba(255,107,107,0.18)',
    },
    live: {
      label:     'Live',
      badgeClass:'badge--live',
      bg:        'linear-gradient(145deg,#141000 0%,#241e00 100%)',
      glowColor: 'rgba(255,209,102,0.18)',
    },
  };

  /* ── SVG icon strings ───────────────────────────────── */
  var ICONS = {
    thumbUp: [
      '<svg width="14" height="14" viewBox="0 0 24 24" fill="none"',
      ' stroke="currentColor" stroke-width="2" stroke-linecap="round"',
      ' stroke-linejoin="round" aria-hidden="true">',
      '<path d="M14 9V5a3 3 0 0 0-3-3l-4 9v11h11.28a2 2 0 0 0 2-1.7l1.38-9a2',
      ' 2 0 0 0-2-2.3H14z"/>',
      '<path d="M7 22H4a2 2 0 0 1-2-2v-7a2 2 0 0 1 2-2h3"/>',
      '</svg>',
    ].join(''),

    thumbDown: [
      '<svg width="14" height="14" viewBox="0 0 24 24" fill="none"',
      ' stroke="currentColor" stroke-width="2" stroke-linecap="round"',
      ' stroke-linejoin="round" aria-hidden="true">',
      '<path d="M10 15v4a3 3 0 0 0 3 3l4-9V2H5.72a2 2 0 0 0-2 1.7l-1.38 9a2',
      ' 2 0 0 0 2 2.3H10z"/>',
      '<path d="M17 2h2.67A2.31 2.31 0 0 1 22 4v7a2.31 2.31 0 0 1-2.33 2H17"/>',
      '</svg>',
    ].join(''),

    flag: [
      '<svg width="14" height="14" viewBox="0 0 24 24" fill="none"',
      ' stroke="currentColor" stroke-width="2" stroke-linecap="round"',
      ' stroke-linejoin="round" aria-hidden="true">',
      '<path d="M4 15s1-1 4-1 5 2 8 2 4-1 4-1V3s-1 1-4 1-5-2-8-2-4 1-4 1z"/>',
      '<line x1="4" y1="22" x2="4" y2="15"/>',
      '</svg>',
    ].join(''),

    star: [
      '<svg width="12" height="12" viewBox="0 0 24 24" fill="currentColor"',
      ' aria-hidden="true">',
      '<polygon points="12 2 15.09 8.26 22 9.27 17 14.14 18.18 21.02',
      ' 12 17.77 5.82 21.02 7 14.14 2 9.27 8.91 8.26 12 2"/>',
      '</svg>',
    ].join(''),

    location: [
      '<svg width="12" height="12" viewBox="0 0 24 24" fill="none"',
      ' stroke="currentColor" stroke-width="2" stroke-linecap="round"',
      ' stroke-linejoin="round" aria-hidden="true">',
      '<path d="M21 10c0 7-9 13-9 13s-9-6-9-13a9 9 0 0 1 18 0z"/>',
      '<circle cx="12" cy="10" r="3"/>',
      '</svg>',
    ].join(''),

    publish: [
      '<svg width="14" height="14" viewBox="0 0 24 24" fill="none"',
      ' stroke="currentColor" stroke-width="2" stroke-linecap="round"',
      ' stroke-linejoin="round" aria-hidden="true">',
      '<path d="M21 15v4a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2v-4"/>',
      '<polyline points="17 8 12 3 7 8"/>',
      '<line x1="12" y1="3" x2="12" y2="15"/>',
      '</svg>',
    ].join(''),

    unpublish: [
      '<svg width="14" height="14" viewBox="0 0 24 24" fill="none"',
      ' stroke="currentColor" stroke-width="2" stroke-linecap="round"',
      ' stroke-linejoin="round" aria-hidden="true">',
      '<path d="M21 15v4a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2v-4"/>',
      '<polyline points="7 16 12 21 17 16"/>',
      '<line x1="12" y1="21" x2="12" y2="9"/>',
      '</svg>',
    ].join(''),
  };

  /* ── Helpers ────────────────────────────────────────── */
  function formatCount(n) {
    if (!n) return '0';
    if (n >= 1000) return (n / 1000).toFixed(1) + 'k';
    return String(n);
  }

  function buildProgressHTML(game) {
    if (game.progress == null) {
      return '<span class="gc-progress__label gc-progress__label--idle">Not started</span>';
    }
    if (game.progress >= 100) {
      return '<span class="gc-progress__label gc-progress__label--done">✓ Completed</span>';
    }
    return [
      '<div class="gc-progress__track"',
      ' role="progressbar"',
      ' aria-valuenow="' + game.progress + '"',
      ' aria-valuemin="0"',
      ' aria-valuemax="100"',
      ' aria-label="' + (game.progressLabel || game.progress + '% complete') + '">',
      '  <div class="gc-progress__fill" style="width:' + game.progress + '%"></div>',
      '</div>',
      '<span class="gc-progress__label">' + (game.progressLabel || game.progress + '% done') + '</span>',
    ].join('');
  }

  /* ── Card factory ────────────────────────────────────── */
  /**
   * create(game) → HTMLElement
   * Accepts a game data object and returns a ready-to-append article element.
   */
  function create(game, options) {
    options = options || {};
    var hideProgress  = options.hideProgress || false;
    var showPublish   = options.showPublish || false;
    var showUnpublish = options.showUnpublish || false;
    var showRemove    = options.showRemove || false;

    var mode    = MODE[game.mode] || MODE.solo;
    var article = document.createElement('article');

    article.className = 'game-card' + (game.featured ? ' game-card--featured' : '');
    article.dataset.gameId = game.id;
    article.tabIndex  = 0;
    article.setAttribute('role', 'listitem');
    article.setAttribute('aria-label', game.title + ' — ' + mode.label + ' game');

    /* Cover: image or emoji placeholder */
    var coverMediaHTML = game.image
      ? '<img src="' + game.image + '" alt="' + game.title + '" loading="lazy" />'
      : '<span class="gc-cover__emoji" aria-hidden="true">' + (game.emoji || '🎮') + '</span>';

    var localVotes = {};
    try { localVotes = JSON.parse(localStorage.getItem('warg_votes') || '{}'); } catch { /* ignore */ }
    var userVote = game.userVote || localVotes[game.id] || null;

    article.innerHTML = [

      /* ── Cover ── */
      '<div class="gc-cover" style="background:' + mode.bg + ';--card-glow:' + mode.glowColor + '">',
        coverMediaHTML,
        '<span class="gc-cover__badge ' + mode.badgeClass + '">' + mode.label + '</span>',
        (showRemove ? 
          '<button class="gc-cover__menu-btn" data-action="remove-menu" aria-label="Menu" aria-expanded="false">' +
            '<svg style="pointer-events: none;" width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">' +
              '<circle cx="12" cy="12" r="1"/><circle cx="12" cy="5" r="1"/><circle cx="12" cy="19" r="1"/>' +
            '</svg>' +
          '</button>' +
          '<div class="gc-menu-dropdown" aria-hidden="true">' +
            '<button class="gc-menu-item" data-action="remove-recent">' +
              '<svg style="pointer-events: none;" width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><line x1="18" y1="6" x2="6" y2="18"></line><line x1="6" y1="6" x2="18" y2="18"></line></svg>' +
              'Remove from Recent' +
            '</button>' +
          '</div>'
        : ''),
      '</div>',

      /* ── Body ── */
      '<div class="gc-body">',

        /* Title */
        '<h3 class="gc-title">' + game.title + '</h3>',

        /* Caption */
        '<p class="gc-caption">' + game.caption + '</p>',

        /* Progress */
        (hideProgress ? '' : (
          '<div class="gc-progress">' +
            buildProgressHTML(game) +
          '</div>'
        )),

        /* Author */
        '<div class="gc-author">',
          '<span class="gc-author__avatar" aria-hidden="true">' + game.author.initials + '</span>',
          '<span class="gc-author__name">' + game.author.name + '</span>',
        '</div>',

        /* Actions */
        '<div class="gc-actions">',

          (showPublish ? (
            '<button class="gc-action gc-action--publish" data-action="publish"' +
            ' aria-label="Publish game" style="width: 100%; justify-content: center; gap: var(--space-2); color: var(--color-success); border-color: rgba(51, 255, 51, 0.2);">' +
              ICONS.publish +
              '<span class="gc-action__count">Publish WARG</span>' +
            '</button>'
          ) : showUnpublish ? (
            '<button class="gc-action gc-action--unpublish" data-action="unpublish"' +
            ' aria-label="Unpublish game" style="width: 100%; justify-content: center; gap: var(--space-2); color: var(--color-warning); border-color: rgba(255, 209, 102, 0.2);">' +
              ICONS.unpublish +
              '<span class="gc-action__count">Unpublish WARG</span>' +
            '</button>'
          ) : (
            '<button class="gc-action' + (userVote === 'like' ? ' is-active' : '') + '" data-action="like"' +
            ' aria-label="Like" aria-pressed="' + (userVote === 'like' ? 'true' : 'false') + '">' +
              ICONS.thumbUp +
              '<span class="gc-action__count">' + formatCount(game.likes) + '</span>' +
            '</button>' +

            '<button class="gc-action' + (userVote === 'dislike' ? ' is-active' : '') + '" data-action="dislike"' +
            ' aria-label="Dislike" aria-pressed="' + (userVote === 'dislike' ? 'true' : 'false') + '">' +
              ICONS.thumbDown +
              '<span class="gc-action__count">' + formatCount(game.dislikes) + '</span>' +
            '</button>' +

            '<button class="gc-action gc-action--flag" data-action="flag"' +
            ' aria-label="Flag content" aria-pressed="false">' +
              ICONS.flag +
            '</button>'
          )),

        '</div>', /* gc-actions */

      '</div>', /* gc-body */

    ].join('');

    /* ── Wire interaction ── */
    _attachEvents(article, game);

    return article;
  }

  /* ── Event handling ─────────────────────────────────── */
  function _attachEvents(article) {
    /* Action buttons: like / dislike / flag (mutually exclusive: like ↔ dislike) */
    article.addEventListener('click', function (e) {
      var btn = e.target.closest('[data-action]');
      if (!btn) {
        /* Clicking the card body opens the game */
        _onCardOpen(article);
        return;
      }
      e.preventDefault();
      e.stopPropagation();

      var action = btn.dataset.action;

      if (action === 'publish' || action === 'unpublish') {
        article.dispatchEvent(new CustomEvent('warg:' + action, {
          bubbles: true,
          detail: { 
            gameId: article.dataset.gameId, 
            gameTitle: article.querySelector('.gc-title').textContent 
          }
        }));
        return;
      }

      var argId = article.dataset.gameId;

      if (action === 'remove-menu') {
        var dropdown = article.querySelector('.gc-menu-dropdown');
        var isOpen = dropdown.classList.contains('is-open');
        
        // Close all others first
        document.querySelectorAll('.gc-menu-dropdown.is-open').forEach(function(el) {
          el.classList.remove('is-open');
          el.setAttribute('aria-hidden', 'true');
          var sib = el.previousElementSibling;
          if (sib) sib.setAttribute('aria-expanded', 'false');
        });

        if (!isOpen) {
          dropdown.classList.add('is-open');
          dropdown.setAttribute('aria-hidden', 'false');
          btn.setAttribute('aria-expanded', 'true');
        }
        return;
      }

      if (action === 'remove-recent') {
        var menuDropdown = article.querySelector('.gc-menu-dropdown');
        if (menuDropdown) {
          menuDropdown.classList.remove('is-open');
          menuDropdown.setAttribute('aria-hidden', 'true');
        }
        
        if (typeof window.RemoveModal !== 'undefined') {
          if (!window._gameCardRemoveModal) window._gameCardRemoveModal = new window.RemoveModal();
          window._gameCardRemoveModal.open(argId, article.querySelector('.gc-title').textContent);
        } else {
          import('./RemoveModal.js?v=1').then(module => {
            if (!window._gameCardRemoveModal) window._gameCardRemoveModal = new module.RemoveModal();
            window._gameCardRemoveModal.open(argId, article.querySelector('.gc-title').textContent);
          }).catch(err => {
            console.error('[GameCard] Failed to load RemoveModal:', err);
          });
        }
        return;
      }

      if (action === 'flag') {
        if (typeof window.FlagModal !== 'undefined') {
          // Use a singleton flag modal instance for GameCard
          if (!window._gameCardFlagModal) window._gameCardFlagModal = new window.FlagModal();
          window._gameCardFlagModal.open(argId, 'Report Game');
        } else {
          // Dynamically import the module (relative to the HTML page loading it)
          import('./FlagModal.js?v=2').then(module => {
            if (!window._gameCardFlagModal) window._gameCardFlagModal = new module.FlagModal();
            window._gameCardFlagModal.open(argId, 'Report Game');
          }).catch(err => {
            console.error('[GameCard] Failed to load FlagModal:', err);
          });
        }
        return; // Don't toggle state on flag button
      }

      var isPressed = btn.getAttribute('aria-pressed') === 'true';
      
      var likeCountSpan = article.querySelector('[data-action="like"] .gc-action__count');
      var dislikeCountSpan = article.querySelector('[data-action="dislike"] .gc-action__count');
      
      var parseCount = function(span) { return span ? parseInt(span.textContent.replace(/,/g, ''), 10) || 0 : 0; };
      var currentLikes = parseCount(likeCountSpan);
      var currentDislikes = parseCount(dislikeCountSpan);

      btn.setAttribute('aria-pressed', String(!isPressed));
      btn.classList.toggle('is-active', !isPressed);

      /* Mutual exclusion: liking removes dislike state and vice-versa. Also update optimistic counts. */
      if (action === 'like') {
        currentLikes += isPressed ? -1 : 1;
        if (!isPressed) {
          var dislike = article.querySelector('[data-action="dislike"]');
          if (dislike && dislike.getAttribute('aria-pressed') === 'true') {
            dislike.setAttribute('aria-pressed', 'false');
            dislike.classList.remove('is-active');
            currentDislikes--;
          }
        }
      } else if (action === 'dislike') {
        currentDislikes += isPressed ? -1 : 1;
        if (!isPressed) {
          var like = article.querySelector('[data-action="like"]');
          if (like && like.getAttribute('aria-pressed') === 'true') {
            like.setAttribute('aria-pressed', 'false');
            like.classList.remove('is-active');
            currentLikes--;
          }
        }
      }
      
      if (likeCountSpan) likeCountSpan.textContent = formatCount(currentLikes);
      if (dislikeCountSpan) dislikeCountSpan.textContent = formatCount(currentDislikes);

      // Persist to localStorage optimistically
      try {
        var votes = JSON.parse(localStorage.getItem('warg_votes') || '{}');
        var likeBtn = article.querySelector('[data-action="like"]');
        var dislikeBtn = article.querySelector('[data-action="dislike"]');
        
        var newVote = null;
        if (likeBtn && likeBtn.getAttribute('aria-pressed') === 'true') newVote = 'like';
        else if (dislikeBtn && dislikeBtn.getAttribute('aria-pressed') === 'true') newVote = 'dislike';
        
        if (newVote) votes[argId] = newVote;
        else delete votes[argId];
        localStorage.setItem('warg_votes', JSON.stringify(votes));
      } catch { /* ignore */ }

      // Fire API call
      if (typeof api !== 'undefined' && api.voteArg) {
        api.voteArg(argId, action).then(res => {
          if (res && res.success) {
            // Update counts in DOM
            var likeCount = article.querySelector('[data-action="like"] .gc-action__count');
            var dislikeCount = article.querySelector('[data-action="dislike"] .gc-action__count');
            if (likeCount) likeCount.textContent = formatCount(res.like_count);
            if (dislikeCount) dislikeCount.textContent = formatCount(res.dislike_count);
          }
        }).catch(err => {
          console.error('[GameCard] Failed to vote:', err);
        });
      }
    });

    /* Keyboard: Enter / Space activates the card (not a button) */
    article.addEventListener('keydown', function (e) {
      if ((e.key === 'Enter' || e.key === ' ') && e.target === article) {
        e.preventDefault();
        _onCardOpen(article);
      }
    });
  }

  function _onCardOpen(article) {
    var title = article.querySelector('.gc-title');
    var gameId = article.dataset.gameId;
    console.log('[WARG] Open game:', title ? title.textContent.trim() : gameId);
    if (window.location.pathname.includes('studio')) {
      window.location.href = 'edit_warg.html?id=' + gameId;
    } else {
      window.location.href = 'game.html?id=' + gameId;
    }
  }

  /* ── renderRow helper ────────────────────────────────── */
  /**
   * renderRow(containerId, gamesArray)
   * Clears the container and appends freshly-built cards.
   *
   * @param {string}   containerId  — id attribute of the .card-row element
   * @param {object[]} games        — array of game data objects
   * @param {object}   options      — configuration options (e.g. hideProgress)
   */
  function renderRow(containerId, games, options) {
    var container = document.getElementById(containerId);
    if (!container) {
      console.warn('[GameCard] Container not found:', containerId);
      return;
    }
    /* DocumentFragment batches DOM insertions for one reflow */
    var frag = document.createDocumentFragment();
    games.forEach(function (game) { frag.appendChild(create(game, options)); });
    container.innerHTML = '';
    container.appendChild(frag);
  }

  /* ── renderSkeletons helper ────────────────────────────── */
  function renderSkeletons(containerId, count) {
    count = count || 5;
    var container = document.getElementById(containerId);
    if (!container) return;
    var skeletons = '';
    for (var i = 0; i < count; i++) {
      skeletons += '<div class="game-card game-card--skeleton" aria-hidden="true">' +
        '<div class="gc-cover" style="background:var(--color-surface-2)"></div>' +
        '<div class="gc-body">' +
          '<div class="skeleton-line skeleton-line--title"></div>' +
          '<div class="skeleton-line skeleton-line--caption"></div>' +
          '<div class="skeleton-line skeleton-line--caption" style="width:60%"></div>' +
        '</div>' +
      '</div>';
    }
    container.innerHTML = skeletons;
  }

  /* ── Global menu closer ── */
  if (typeof window !== 'undefined') {
    window.addEventListener('click', function(e) {
      if (e.target.closest('[data-action="remove-menu"]')) return;
      document.querySelectorAll('.gc-menu-dropdown.is-open').forEach(function(el) {
        el.classList.remove('is-open');
        el.setAttribute('aria-hidden', 'true');
        var btn = el.previousElementSibling;
        if (btn) btn.setAttribute('aria-expanded', 'false');
      });
    });
  }

  /* ── Public API ─────────────────────────────────────── */
  return { create: create, renderRow: renderRow, renderSkeletons: renderSkeletons };

}());

/**
 * WARG Platform — Catalogue Script
 * Handles rendering the game catalogue grid, filter chips, and pagination.
 * Data is fetched from the live API; works for guests and logged-in users.
 */

document.addEventListener('DOMContentLoaded', async () => {
  const catalogueGrid = document.getElementById('catalogue-grid');
  if (!catalogueGrid || typeof GameCard === 'undefined' || typeof api === 'undefined') return;

  // ── Loading skeleton ──
  let skeletonHtml = '';
  for (let i = 0; i < 12; i++) {
    skeletonHtml +=
      '<div class="game-card game-card--skeleton" aria-hidden="true">' +
        '<div class="gc-cover" style="background:var(--color-surface-2)"></div>' +
        '<div class="gc-body">' +
          '<div class="skeleton-line skeleton-line--title"></div>' +
          '<div class="skeleton-line skeleton-line--caption"></div>' +
          '<div class="skeleton-line skeleton-line--caption" style="width:60%"></div>' +
        '</div>' +
      '</div>';
  }
  catalogueGrid.innerHTML = skeletonHtml;

  // ── Fetch all published ARGs ──
  let allArgs = [];
  try {
    allArgs = await api.getArgs();
  } catch (err) {
    console.error('[Catalogue] Failed to load ARGs:', err);
    catalogueGrid.innerHTML =
      '<p style="color:var(--color-text-muted);grid-column:1/-1;text-align:center;padding:2rem">' +
      'Unable to load games. Please check your connection and try again.</p>';
    return;
  }

  let activeFilter = 'all'; // track active filter chip

  // ── Render helpers ──
  function getFilteredArgs() {
    if (activeFilter === 'all') return allArgs;
    return allArgs.filter(a => a.mode === activeFilter);
  }

  function renderGrid() {
    const filtered = getFilteredArgs();
    catalogueGrid.innerHTML = '';

    if (filtered.length === 0) {
      catalogueGrid.innerHTML =
        '<p style="color:var(--color-text-muted);grid-column:1/-1;text-align:center;padding:2rem">' +
        'No games match this filter.</p>';
      return;
    }

    const frag = document.createDocumentFragment();
    filtered.forEach(game => frag.appendChild(GameCard.create(game)));
    catalogueGrid.appendChild(frag);
  }

  // Initial render
  renderGrid();

  // ── Filter chips ──
  const filterChips = document.querySelectorAll('.filter-chip');
  filterChips.forEach(chip => {
    chip.addEventListener('click', () => {
      filterChips.forEach(c => c.classList.remove('active'));
      chip.classList.add('active');
      activeFilter = chip.dataset.filter || 'all';
      renderGrid();
    });
  });

  // ── Pagination (cosmetic fade — real pagination would need server-side offset) ──
  const paginationPages = document.querySelectorAll('.pagination-page');
  paginationPages.forEach(pageBtn => {
    pageBtn.addEventListener('click', () => {
      document.querySelectorAll('.pagination-page.active').forEach(el => el.classList.remove('active'));
      pageBtn.classList.add('active');
      catalogueGrid.style.opacity = '0.5';
      setTimeout(() => { catalogueGrid.style.opacity = '1'; }, 300);
    });
  });
});
